            BBOX.balanceOf(address(this)) * 90 / 100, 0, path, address(this), block.timestamp
        );
    }
}

contract TransferBBOXHelp {
    IERC20 BBOX = IERC20(0x5DfC7f3EbBB9Cbfe89bc3FB70f750Ee229a59F8c);

